values ('showcase-solsteam', 'Sol & Steam Café', 'coffee', array['Latino-owned']::text[], false, 37.9375, -122.348, '1200 Macdonald Ave, Richmond, CA', '$$', 'A cozy neighborhood café serving specialty coffee, house-made pastries, and Latin-inspired bites. A space for good food, good people, and brighter days.', array['showcase:solsteam-cover']::text[], $j$[{"day": "Mon", "open": "7:00", "close": "18:00"}, {"day": "Tue", "open": "7:00", "close": "18:00"}, {"day": "Wed", "open": "7:00", "close": "18:00"}, {"day": "Thu", "open": "7:00", "close": "18:00"}, {"day": "Fri", "open": "7:00", "close": "18:00"}, {"day": "Sat", "open": "7:00", "close": "18:00"}, {"day": "Sun", "open": "7:00", "close": "18:00"}]$j$::jsonb, $j$[{"id": "sol-vanilla-latte", "name": "Vanilla Latte", "price": 5.25, "description": "Espresso, house vanilla, steamed oat milk", "sectionId": "coffee", "photo": "showcase:drink", "isPopular": true, "options": [{"id": "size", "name": "Size", "required": true, "multiple": false, "choices": [{"id": "s0", "name": "12 oz", "price": 0}, {"id": "s1", "name": "16 oz", "price": 0.75}]}, {"id": "milk", "name": "Milk", "required": true, "multiple": false, "choices": [{"id": "whole", "name": "Whole milk", "price": 0}, {"id": "2pct", "name": "2%", "price": 0}, {"id": "oat", "name": "Oat milk", "price": 0.75}, {"id": "almond", "name": "Almond milk", "price": 0.75}]}, {"id": "addons", "name": "Add-ons", "required": false, "multiple": true, "choices": [{"id": "shot", "name": "Extra espresso shot", "price": 1.0}, {"id": "syrup", "name": "Extra syrup pump", "price": 0.5}, {"id": "foam", "name": "Cold foam", "price": 0.5}]}]}, {"id": "sol-almond-croissant", "name": "Almond Croissant", "price": 4.75, "description": "Buttery, flaky, house-baked daily", "sectionId": "pastries", "photo": "showcase:solsteam-cover", "isPopular": true}, {"id": "sol-chorizo-sandwich", "name": "Chorizo Breakfast Sandwich", "price": 8.5, "description": "Scrambled eggs, chorizo, cheese, avocado, aioli", "sectionId": "breakfast", "photo": "showcase:drink", "isPopular": true}, {"id": "sol-cafe-de-olla", "name": "Café de Olla", "price": 4.25, "description": "Coffee brewed with piloncillo and cinnamon", "sectionId": "coffee", "photo": "showcase:drink", "isPopular": false, "options": [{"id": "temp", "name": "Temperature", "required": true, "multiple": false, "choices": [{"id": "iced", "name": "Iced", "price": 0}, {"id": "hot", "name": "Hot", "price": 0}]}]}, {"id": "sol-horchata-latte", "name": "Horchata Latte", "price": 5.75, "description": "Espresso, house horchata, cinnamon", "sectionId": "coffee", "photo": "showcase:drink", "isPopular": false, "options": [{"id": "temp", "name": "Temperature", "required": true, "multiple": false, "choices": [{"id": "iced", "name": "Iced", "price": 0}, {"id": "hot", "name": "Hot", "price": 0}]}, {"id": "milk", "name": "Milk", "required": true, "multiple": false, "choices": [{"id": "whole", "name": "Whole milk", "price": 0}, {"id": "2pct", "name": "2%", "price": 0}, {"id": "oat", "name": "Oat milk", "price": 0.75}, {"id": "almond", "name": "Almond milk", "price": 0.75}]}]}, {"id": "sol-concha", "name": "Concha", "price": 3.25, "description": "Soft sweet bread with a vanilla shell", "sectionId": "pastries", "photo": "showcase:solsteam-cover", "isPopular": false}]$j$::jsonb, $j$[{"id": "coffee", "name": "Coffee"}, {"id": "pastries", "name": "Pastries"}, {"id": "breakfast", "name": "Breakfast"}]$j$::jsonb, $j${"version": 1, "colors": {"primary": "#E94F6D", "background": "#FFF9F4", "text": "#2B211C"}, "fonts": {"heading": "system", "accent": "script"}, "background": {"image": "showcase:zebra", "fit": "fill", "size": 65, "strength": 90, "fixedWhileScrolling": true}, "cards": "solid", "layout": "panel", "hero": {"style": "cover", "image": null, "logo": "showcase:solsteam-logo", "eyebrow": null, "headline": null, "tagline": null, "subtext": null, "primaryCta": "Order ahead", "secondaryCta": "Directions", "secondaryAction": "directions"}, "d