on conflict (id) do update set name = excluded.name, category = excluded.category, tags = excluded.tags, is_home_based = excluded.is_home_based, lat = excluded.lat, lng = excluded.lng, address = excluded.address, price_range = excluded.price_range, description = excluded.description, photos = excluded.photos, hours = excluded.hours, menu = excluded.menu, menu_sections = excluded.menu_sections, storefront = excluded.storefront, storefront_draft = excluded.storefront_draft, owner_user_id = excluded.owner_user_id, published = excluded.published, accepting_orders = excluded.accepting_orders, prep_time = excluded.prep_time;
